<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/scenarios';import * as runs from '../api/runs';import {useAction} from '../hooks/useAction';import {crewExample,dispatchExample} from '../utils/example';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import ScenarioStrip from '../components/ScenarioStrip.vue';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const emit=defineEmits<{open:[string]}>();const name=ref('检修工作包·新风险情景'),pkg=ref('demo-package'),deadline=ref(32),samples=ref(1500),seed=ref(2410),crewText=ref('[]'),dispatchText=ref('[]');const pkgTasks=computed(()=>props.data.packages.find(p=>p.id===pkg.value)?.tasks??[]);const{busy,error,notice,act}=useAction();const parse=(t:string,label:string)=>{try{return JSON.parse(t)}catch{throw new Error(label+'JSON解析失败，请检查格式')}};async function save(){await create({name:name.value,package_id:pkg.value,deadline:deadline.value,samples:samples.value,seed:seed.value,crews:parse(crewText.value,'班组'),dispatch:parse(dispatchText.value,'派工')});await props.refresh()}</script><template><Heading index="04 / IMMUTABLE SCENARIOS" title="截止期只问概率，不改写时差。" detail="每次保存新增工作包情景版本，冻结任务、FS边、三点范围与班组配置。CPM/每次模拟LF均基于项目实际完工；配置班组后逐样本按容量与派工规则重算开工完工。"/><section v-if="canWrite" class="form-section"><form class="form-grid" @submit.prevent="act(save,'风险情景快照已冻结，可提交后台推演')"><label>情景名称<input aria-label="情景名称" v-model="name" required/></label><label>情景工作包<select aria-label="情景工作包" v-model="pkg"><option v-for="p in data.packages" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>截止期 / 小时<input aria-label="截止期小时" type="number" min="0" step="any" v-model.number="deadline"/></label><label>模拟样本数<input aria-label="模拟样本数" type="number" min="100" max="5000" step="1" v-model.number="samples"/></label><label>固定seed<input aria-label="固定seed" type="number" min="0" max="2147483647" step="1" v-model.number="seed"/></label><label class="span-all">班组容量JSON（crew_id+capacity；留[]为不限班组）<textarea aria-label="班组容量JSON" v-model="crewText" rows="3"/></label><div class="actions span-all"><button type="button" @click="crewText=JSON.stringify(crewExample(),null,2)">填入双班组示例</button><button type="button" @click="dispatchText=JSON.stringify(dispatchExample(pkgTasks),null,2)">按当前工作包生成派工草稿</button></div><label class="span-all">派工JSON（每任务task_id+priority+crews占用；配置班组后须覆盖全部任务，超容量拒绝）<textarea aria-label="派工JSON" v-model="dispatchText" rows="5"/></label><button class="primary" :disabled="busy">冻结风险情景</button></form><Notice :error="error" :notice="notice"/></section><Empty v-if="!data.scenarios.length">先导入工作包并建立无环FS依赖，再锁定截止期、样本数与seed。</Empty><article v-for="s in data.scenarios" :key="s.id" class="scenario-row"><div><p class="eyebrow">SNAPSHOT v{{s.version}} / {{s.snapshot.package.tasks.length}} TASKS / {{s.snapshot.dependencies.length}} EDGES{{s.snapshot.crews?.length?' / '+s.snapshot.crews.length+' CREWS':''}}</p><h2>{{s.name}}</h2><p>{{s.snapshot.package.source}}</p><ScenarioStrip :scenario="s"/></div><div><button v-if="canWrite" :disabled="busy" @click="act(async()=>{const r=await runs.create({scenario_id:s.id});await refresh();emit('open',r.id)},'风险任务已提交Redis')">运行CPM与风险 →</button><small>{{data.runs.filter(r=>r.scenario_id===s.id).length}}次独立运行</small></div></article><p class="footnote"><span>Beta-PERT λ=4。a=m=b为常数，其余alpha=1+4(m-a)/(b-a)，beta=1+4(b-m)/(b-a)。固定seed与ID顺序复现，工期独立假设不包含天气共因。</span><span>班组受限情景：任务全部前置完工后就绪，同一时刻按(优先级,任务ID)派工，先开工先占用、工期内不抢占；超容量需求在冻结时拒绝。</span></p></template>